CREATE TYPE campaign_status AS ENUM ('draft','queued','preparing','running','passed','failed','cancelled','timed_out','error');
CREATE TYPE import_status AS ENUM ('pending','verified','unverified','failed');
CREATE TYPE outbox_status AS ENUM ('pending','delivered','failed');
CREATE TABLE users (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), wallet_address varchar(42) NOT NULL UNIQUE, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE sessions (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL REFERENCES users(id) ON DELETE CASCADE, token_hash varchar(64) NOT NULL UNIQUE, expires_at timestamptz NOT NULL, revoked_at timestamptz, created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX sessions_user_expiry_idx ON sessions(user_id, expires_at);
CREATE TABLE contracts (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), owner_id uuid NOT NULL REFERENCES users(id) ON DELETE RESTRICT, chain_id integer NOT NULL CHECK (chain_id = 4663), address varchar(42) NOT NULL, import_status import_status NOT NULL DEFAULT 'pending', verified boolean NOT NULL DEFAULT false, name text, compiler_version text, metadata jsonb, abi jsonb, provenance_url text, provenance_fetched_at timestamptz, created_at timestamptz NOT NULL DEFAULT now());
CREATE UNIQUE INDEX contracts_owner_chain_address_uq ON contracts(owner_id,chain_id,address);
CREATE INDEX contracts_owner_created_idx ON contracts(owner_id,created_at);
CREATE TABLE contract_sources (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), contract_id uuid NOT NULL REFERENCES contracts(id) ON DELETE RESTRICT, path text NOT NULL, content_digest varchar(66) NOT NULL, source_text text NOT NULL, provenance_url text NOT NULL, provenance_fetched_at timestamptz NOT NULL);
CREATE UNIQUE INDEX contract_sources_path_uq ON contract_sources(contract_id,path);
CREATE INDEX contract_sources_contract_idx ON contract_sources(contract_id);
CREATE TABLE campaigns (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), owner_id uuid NOT NULL REFERENCES users(id) ON DELETE RESTRICT, contract_id uuid NOT NULL REFERENCES contracts(id) ON DELETE RESTRICT, status campaign_status NOT NULL DEFAULT 'queued', snapshot_block_number bigint NOT NULL CHECK (snapshot_block_number >= 0), snapshot_block_hash varchar(66) NOT NULL, harness_digest varchar(66) NOT NULL, build_digest varchar(66) NOT NULL, seed text NOT NULL, runs integer NOT NULL CHECK (runs > 0), depth integer NOT NULL CHECK (depth > 0), timeout_seconds integer NOT NULL CHECK (timeout_seconds > 0), engine_version text, cancel_requested_at timestamptz, queued_at timestamptz NOT NULL DEFAULT now(), started_at timestamptz, finished_at timestamptz, created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX campaigns_owner_status_created_idx ON campaigns(owner_id,status,created_at);
CREATE INDEX campaigns_contract_idx ON campaigns(contract_id);
CREATE TABLE invariants (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), campaign_id uuid NOT NULL REFERENCES campaigns(id) ON DELETE RESTRICT, name text NOT NULL, description text, template text, source_digest varchar(66), configuration jsonb NOT NULL, enabled boolean NOT NULL DEFAULT true, created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX invariants_campaign_idx ON invariants(campaign_id);
CREATE TABLE campaign_events (campaign_id uuid NOT NULL REFERENCES campaigns(id) ON DELETE RESTRICT, sequence bigint NOT NULL, event_type varchar(40) NOT NULL, payload jsonb NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), PRIMARY KEY(campaign_id,sequence));
CREATE INDEX campaign_events_replay_idx ON campaign_events(campaign_id,sequence);
CREATE TABLE counterexamples (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), campaign_id uuid NOT NULL REFERENCES campaigns(id) ON DELETE RESTRICT, invariant_id uuid REFERENCES invariants(id) ON DELETE RESTRICT, call_sequence jsonb NOT NULL, trace_artifact_key text, trace_digest varchar(66), replay_manifest jsonb NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX counterexamples_campaign_idx ON counterexamples(campaign_id);
CREATE TABLE artifacts (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), campaign_id uuid NOT NULL REFERENCES campaigns(id) ON DELETE RESTRICT, object_key text NOT NULL UNIQUE, media_type text NOT NULL, digest varchar(66) NOT NULL, byte_count bigint NOT NULL, retain_until timestamptz, created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX artifacts_campaign_idx ON artifacts(campaign_id);
CREATE TABLE campaign_attempts (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), campaign_id uuid NOT NULL REFERENCES campaigns(id) ON DELETE RESTRICT, attempt_number integer NOT NULL, status campaign_status NOT NULL, worker_id text, started_at timestamptz, finished_at timestamptz, error_code text, created_at timestamptz NOT NULL DEFAULT now());
CREATE UNIQUE INDEX campaign_attempt_number_uq ON campaign_attempts(campaign_id,attempt_number);
CREATE INDEX campaign_attempt_campaign_idx ON campaign_attempts(campaign_id);
CREATE TABLE outbox (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), topic text NOT NULL, aggregate_id uuid NOT NULL, payload jsonb NOT NULL, status outbox_status NOT NULL DEFAULT 'pending', attempts integer NOT NULL DEFAULT 0, available_at timestamptz NOT NULL DEFAULT now(), delivered_at timestamptz, created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX outbox_dispatch_idx ON outbox(status,available_at,created_at);
